import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.Bw5kJGsQ.js";const p=JSON.parse(`{"title":"Architecture overview","description":"The engine's layers, from the main loop down to resources, input and addons.","frontmatter":{"id":"architecture","title":"Architecture overview","order":1,"description":"The engine's layers, from the main loop down to resources, input and addons."},"headers":[],"relativePath":"manual/architecture.md","filePath":"en/manual/architecture.md"}`),s={name:"manual/architecture.md"};function c(d,e,n,i,l,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h1><p>ATMO is a C++23 cross-platform 2D game engine built around an Entity Component System using <a href="https://www.flecs.dev/" target="_blank" rel="noreferrer">Flecs</a>.</p><h2 id="engine" tabindex="-1">The engine <a class="header-anchor" href="#engine" aria-label="Permalink to &quot;The engine {#engine}&quot;">​</a></h2><p><a href="/docs/latest/api/cpp/class/atmo-core-engine" class="atmo-ref atmo-ref--symbol"><code>core::Engine</code></a> owns the main loop. It initializes SDL, input and logging, then drives the ECS world every frame. Entities are created and destroyed through the <a href="/docs/latest/api/cpp/class/atmo-core-ecs-entityregistry" class="atmo-ref atmo-ref--symbol"><code>EntityRegistry</code></a>, and every scene is rooted in a <a href="/docs/latest/api/cpp/class/atmo-core-ecs-entities-scene" class="atmo-ref atmo-ref--symbol"><code>ecs::entities::Scene</code></a> entity that manages the lifecycle of its children.</p><h2 id="core-systems" tabindex="-1">Core systems <a class="header-anchor" href="#core-systems" aria-label="Permalink to &quot;Core systems {#core-systems}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/docs/latest/api/cpp/class/atmo-core-resource-resourcemanager" class="atmo-ref atmo-ref--symbol"><code>ResourceManager</code></a></td><td>Handle-based loading and caching of images, fonts and scripts</td></tr><tr><td><a href="/docs/latest/api/cpp/class/atmo-core-inputmanager" class="atmo-ref atmo-ref--symbol"><code>InputManager</code></a></td><td>Keyboard, joystick and controller input through SDL3</td></tr><tr><td><a href="/docs/latest/api/cpp/class/atmo-core-event-eventregistry" class="atmo-ref atmo-ref--symbol"><code>EventRegistry</code></a></td><td>Observer-style event dispatch</td></tr><tr><td><a href="/docs/latest/api/cpp/class/atmo-project-projectmanager" class="atmo-ref atmo-ref--symbol"><code>ProjectManager</code></a></td><td>Reads <code>.atmo</code> project files and mounts the virtual file system</td></tr><tr><td><a href="/docs/latest/api/cpp/class/atmo-meta-metaregistry" class="atmo-ref atmo-ref--symbol"><code>MetaRegistry</code></a></td><td>Runtime type information used for serialization and the editor</td></tr></tbody></table><h2 id="addons" tabindex="-1">Addons <a class="header-anchor" href="#addons" aria-label="Permalink to &quot;Addons {#addons}&quot;">​</a></h2><p>Addons are declared with an <code>addon.json</code> manifest. An <a href="/docs/latest/api/cpp/class/atmo-addon-addon" class="atmo-ref atmo-ref--symbol"><code>Addon</code></a> whose <code>atmo_version</code> does not match the running engine is rejected with <a href="/docs/latest/api/cpp/class/atmo-addon-addon-addonloadexception" class="atmo-ref atmo-ref--symbol"><code>Addon::AddonLoadException</code></a>. Addons may ship a native library exporting an entry point declared with <a href="/docs/latest/api/cpp/file/src-addon-addon-hpp#atmo-register-addon" class="atmo-ref atmo-ref--symbol"><code>ATMO_REGISTER_ADDON</code></a>, which receives an <a href="/docs/latest/api/cpp/class/atmo-addon-atmoapi" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI</code></a> giving access to the engine&#39;s core systems.</p><p>To keep this page accurate, every symbol above is a reference checked at build time: see <a href="/docs/latest/contributing/writing-documentation#references" class="atmo-ref atmo-ref--page" data-preview="Page ids, references to pages and C++ symbols, and how to preview your changes.">References</a>.</p>',9)])])}const f=a(s,[["render",c]]);export{p as __pageData,f as default};
